	req = httptest.NewRequest(http.MethodPost, "/rules", nil)
	req.Body = jsonBody(badBody)
	rr = httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusBadRequest {
		t.Errorf("expected 400, got %d", rr.Code)
